```
Use `Ref` for `RefCounted` types, and change to using pointer access

```suggestion
#ifdef MODULE_FREETYPE_ENABLED
	CHECK(fontfile.load_dynamic_font("thirdparty/fonts/nofonthasthisname.woff2") == OK);
	CHECK_MESSAGE(fontfile.get_data().is_empty() == true, "Invalid fontfile should not be loaded.");
	ERR_PRINT_ON

	// Load a valid file.
	CHECK(fontfile.load_dynamic_font("thirdparty/fonts/NotoSans_Regular.woff2") == OK);

	// Check fontfile data.
	CHECK_MESSAGE(fontfile.get_data().is_empty() == false, "Fontfile should have been loaded.");
	CHECK_MESSAGE(fontfile.get_font_name() == "Noto Sans", "Loaded correct font name.");
	CHECK_MESSAGE(fontfile.get_font_style_name() == "Regular", "Loaded correct font style.");
	CHECK_MESSAGE(fontfile.get_data().size() == 148480llu, "Whole fontfile was loaded.");

	// Valid glyphs.
	CHECK_MESSAGE(fontfile.get_glyph_index(2, 'a', 0) != 0, "Glyph index for 'a' is valid");
	CHECK_MESSAGE(fontfile.get_glyph_index(2, 'b', 0) != 0, "Glyph index for 'b' is valid");
	CHECK_MESSAGE(fontfile.get_glyph_index(2, 0x0103, 0) != 0, "Glyph index for 'latin small letter a with breve' is valid");
	CHECK_MESSAGE(fontfile.get_glyph_index(2, 0x03a8, 0) != 0, "Glyph index for 'Greek psi' is valid");
	CHECK_MESSAGE(fontfile.get_glyph_index(2, 0x0416, 0) != 0, "Glyph index for 'Cyrillic zhe' is valid");
	CHECK_MESSAGE(fontfile.get_glyph_index(2, '&', 0) != 0, "Glyph index for '&' is valid");

	// Invalid glyphs.
	CHECK_MESSAGE(fontfile.get_glyph_index(2, 0x4416, 0) == 0, "Glyph index is invalid");
	CHECK_MESSAGE(fontfile.get_glyph_index(2, 0x5555, 0) == 0, "Glyph index is invalid");
	CHECK_MESSAGE(fontfile.get_glyph_index(2, 0x2901, 0) == 0, "Glyph index is invalid");
#endif
```

